using Godot;
using System;
using System.Collections.Generic;
using System.Globalization;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ImageWorkspaceOperations
{
    private readonly ImageValueOperations _workspaceValues=new();
    private static readonly (string Key,double Default,Vector2 Range)[] LegacyBasics={("brightness",0,new(-1,1)),("contrast",1,new(0,4)),("saturation",1,new(0,4)),("exposure",0,new(-6,6)),("gamma",1,new(.1f,4)),("hue",0,new(-Mathf.Pi,Mathf.Pi)),("temperature",0,new(-1,1)),("tint",0,new(-1,1))};
    private static void SetBasic(Resource layer,string key,double value){var properties=layer.Get("properties").AsGodotDictionary();if(!properties.ContainsKey("value_basics"))properties["value_basics"]=new Settings();properties["value_basics"].AsGodotDictionary()[key]=value;}
    public void build_value_sliders(Control owner,Resource layer)
    {
        foreach(var entry in LegacyBasics){string key=entry.Key;double fallback=entry.Default;var column=new VBoxContainer{CustomMinimumSize=new Vector2(174,0)};column.AddThemeConstantOverride("separation",0);owner.Get("context").As<Node>().AddChild(column);var row=new HBoxContainer();column.AddChild(row);row.AddChild(new TextureRect{Texture=icon(owner,key),CustomMinimumSize=new Vector2(15,15),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered,SizeFlagsVertical=Control.SizeFlags.ShrinkCenter,Modulate=new Color("7fe3cd")});var label=new Label{Text=key.Capitalize(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};label.AddThemeFontSizeOverride("font_size",12);row.AddChild(label);var amount=new Label();amount.AddThemeFontSizeOverride("font_size",12);row.AddChild(amount);var reset=new Button{Text="↺",TooltipText="Reset "+key,Flat=true};row.AddChild(reset);var slider=new HSlider{MinValue=entry.Range.X,MaxValue=entry.Range.Y,Step=.01,Value=Get(Get(layer.Get("properties").AsGodotDictionary(),"value_basics",new Settings()).AsGodotDictionary(),key,fallback).AsDouble()};column.AddChild(slider);amount.Text=slider.Value.ToString("F2",CultureInfo.InvariantCulture);reset.Disabled=Mathf.IsEqualApprox(slider.Value,fallback);slider.DragStarted+=()=>begin(owner);slider.ValueChanged+=next=>{begin(owner);SetBasic(layer,key,next);amount.Text=next.ToString("F2",CultureInfo.InvariantCulture);reset.Disabled=Mathf.IsEqualApprox(next,fallback);preview(owner);};slider.DragEnded+=_=>commit(owner);slider.FocusExited+=()=>commit(owner);reset.Pressed+=()=>{slider.Value=fallback;commit(owner);};}
    }
    public void populate_values(Control owner,VBoxContainer list,Resource layer,bool ordered)
    {
        clear(list);var properties=layer.Get("properties").AsGodotDictionary();if(!ordered){foreach(var entry in LegacyBasics){string key=entry.Key;slider(owner,list,key.Capitalize(),Get(Get(properties,"value_basics",new Settings()).AsGodotDictionary(),key,entry.Default).AsDouble(),entry.Range.X,entry.Range.Y,Callable.From<double>(value=>SetBasic(layer,key,value)));}button(owner,list,"↺ Reset adjustments",Callable.From(()=>{Action(owner,()=>properties.Remove("value_basics"));populate_values(owner,list,layer,ordered);}),"","");return;}var ops=Get(properties,"value_operations",new GArray()).AsGodotArray();for(int i=0;i<ops.Count;i++){int index=i;var op=ops[i].AsGodotDictionary();string kind=op["type"].AsString();var card=new ImageOperationRow{index=i};card.Connect("reorder_requested",Callable.From<int,int>((from,to)=>{Action(owner,()=>{var item=ops[from];ops.RemoveAt(from);ops.Insert(to,item);});populate_values(owner,list,layer,true);}));card.AddThemeStyleboxOverride("panel",box(new Color("1c2c3a"),new Color("355064"),7,10));list.AddChild(card);var column=new VBoxContainer{MouseFilter=Control.MouseFilterEnum.Pass};card.AddChild(column);var row=new HBoxContainer();column.AddChild(row);row.AddChild(new Label{Text="⠿  "+(i+1)+"  "+kind.Capitalize(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});check(owner,row,"",Get(op,"enabled",true).AsBool(),Callable.From<bool>(value=>op["enabled"]=value));button(owner,row,"↺",Callable.From(()=>{Action(owner,()=>{var replacement=_workspaceValues.new_operation(kind);replacement["enabled"]=Get(op,"enabled",true);ops[index]=replacement;});populate_values(owner,list,layer,true);}),"Reset operation parameters","");button(owner,row,"×",Callable.From(()=>{Action(owner,()=>ops.RemoveAt(index));populate_values(owner,list,layer,true);}),"Remove operation","");if(!op.ContainsKey("a")){if(kind!="invert")number(owner,column,"Amount",Get(op,"amount",1).AsDouble(),Callable.From<double>(value=>op["amount"]=value),-16,64,.01);button(owner,column,"Edit operands",Callable.From(()=>{Action(owner,()=>{var replacement=_workspaceValues.new_operation(kind);double amount=Get(op,"amount",1).AsDouble();replacement["b"].AsGodotDictionary()["value"]=kind=="snap"?1/Math.Max(1,amount):amount;replacement["preserve_hue"]=false;replacement["enabled"]=Get(op,"enabled",true);ops[index]=replacement;});populate_values(owner,list,layer,true);}),"","");continue;}var rebuild=Callable.From(()=>populate_values(owner,list,layer,true));operand_controls(owner,column,"A",op,"a",rebuild);if(kind is not "absolute" and not "invert"){operand_controls(owner,column,"B",op,"b",rebuild);button(owner,column,"⇄ Swap A / B",Callable.From(()=>{Action(owner,()=>{var a=op["a"];op["a"]=op["b"];op["b"]=a;});populate_values(owner,list,layer,true);}),"","");}if(kind is "clamp" or "lerp" or "smoothstep")operand_controls(owner,column,kind=="lerp"?"Weight":"Upper",op,"c",rebuild);if(kind=="snap")check(owner,column,"Preserve hue",Get(op,"preserve_hue",true).AsBool(),Callable.From<bool>(value=>op["preserve_hue"]=value));check(owner,column,"Affect alpha",Get(op,"affect_alpha",false).AsBool(),Callable.From<bool>(value=>op["affect_alpha"]=value));}
    }
    public void operand_controls(Control owner,Control host,string caption,Settings op,string key,Variant rebuild)
    {
        var operand=op[key].AsGodotDictionary();var row=new HBoxContainer();host.AddChild(row);row.AddChild(new Label{Text=caption,CustomMinimumSize=new Vector2(48,0)});var type=new OptionButton{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(type);foreach(string title in new[]{"Pixel value","Float","Vector4 · RGBA"})type.AddItem(title);string kind=Get(operand,"kind","pixel").AsString();type.Select(Array.IndexOf(new[]{"pixel","float","vector"},kind));type.ItemSelected+=index=>{Action(owner,()=>op[key]=new Settings{["kind"]=new[]{"pixel","float","vector"}[(int)index],["value"]=Get(operand,"value",1).AsDouble(),["channels"]=new GArray{1.0,1.0,1.0,1.0}});owner.Call("_invoke_action",rebuild);};if(kind=="float")number(owner,host,"Value",Get(operand,"value",0).AsDouble(),Callable.From<double>(value=>operand["value"]=value),-10000,10000,.01);else if(kind=="vector"){var channels=Get(operand,"channels",new GArray{1.0,1.0,1.0,1.0}).AsGodotArray();operand["channels"]=channels;for(int i=0;i<4;i++){int channel=i;var channelRow=new HBoxContainer();host.AddChild(channelRow);var source=new OptionButton();channelRow.AddChild(source);foreach(string title in new[]{"Constant","Pixel R","Pixel G","Pixel B","Pixel A"})source.AddItem(title);source.Select(channels[i].VariantType==Variant.Type.String?"rgba".IndexOf(channels[i].AsString(),StringComparison.Ordinal)+1:0);source.ItemSelected+=index=>{Action(owner,()=>channels[channel]=index==0?Variant.From(1.0):Variant.From("rgba"[(int)index-1].ToString()));owner.Call("_invoke_action",rebuild);};if(channels[i].VariantType!=Variant.Type.String)number(owner,channelRow,"RGBA"[i].ToString(),channels[i].AsDouble(),Callable.From<double>(value=>channels[channel]=value),-10000,10000,.01);}}
    }
}
